                             CAST(C.[_TIPO] AS varchar(60)) COLLATE DATABASE_DEFAULT AS [TIPO_COMPROBANTE], CAST(C.[CODIGO] AS varchar(38)) COLLATE DATABASE_DEFAULT AS [CODIGO], CAST(C.[DESCFW] AS varchar(200)) COLLATE DATABASE_DEFAULT AS [DESCFW], CAST(C.[FCLIENTE] AS varchar(185)) COLLATE DATABASE_DEFAULT AS [FCLIENTE], CAST(C.[FVEN] AS varchar(10)) COLLATE DATABASE_DEFAULT AS [FVEN], CAST(C.[MOTIVO] AS varchar(3)) COLLATE DATABASE_DEFAULT AS [MOTIVO], CAST(C.[FFCH] AS datetime) AS [FFCH], CAST(C.[FHORA] AS varchar(8)) COLLATE DATABASE_DEFAULT AS [FHORA], CAST(C.[FIMPUESTO] AS decimal(15,2)) AS [FIMPUESTO], CAST(C.[FLETRA] AS varchar(1)) COLLATE DATABASE_DEFAULT AS [FLETRA], CAST(C.[FNUMCOMP] AS decimal(8,0)) AS [FNUMCOMP], CAST(C.[FOBS] AS varchar(250)) COLLATE DATABASE_DEFAULT AS [FOBS], CAST(C.[FPERSON] AS varchar(10)) COLLATE DATABASE_DEFAULT AS [FPERSON], CAST(C.[FSUBTON] AS decimal(15,4)) AS [FSUBTON], CAST(C.[FSUBTOT] AS decimal(15,4)) AS [FSUBTOT], CAST(C.[FTOTAL] AS decimal(15,2)) AS [FTOTAL], CAST(C.[FTURNO] AS decimal(1,0)) AS [FTURNO], CAST(C.[FVUELTO] AS decimal(15,2)) AS [FVUELTO], CAST(C.[GRAVAMEN] AS decimal(15,2)) AS [GRAVAMEN], CAST(C.[HALTAFW] AS varchar(8)) COLLATE DATABASE_DEFAULT AS [HALTAFW], CAST(C.[IDCAJA] AS decimal(2,0)) AS [IDCAJA], CAST(C.[IVASIS] AS decimal(10,2)) AS [IVASIS], CAST(C.[REMITO] AS varchar(15)) COLLATE DATABASE_DEFAULT AS [REMITO], CAST(C.[SIGNOMOV] AS decimal(2,0)) AS [SIGNOMOV], CAST(C.[UALTAFW] AS varchar(100)) COLLATE DATABASE_DEFAULT AS [UALTAFW], CAST(D.[AFECANT] AS decimal(15,2)) AS [AFECANT], CAST(D.[CCOLOR] AS varchar(6)) COLLATE DATABASE_DEFAULT AS [CCOLOR], CAST(D.[EQUIV] AS varchar(20)) COLLATE DATABASE_DEFAULT AS [EQUIV], CAST(D.[FART] AS varchar(15)) COLLATE DATABASE_DEFAULT AS [FART], CAST(D.[FBRUTO] AS decimal(15,4)) AS [FBRUTO], CAST(D.[FCANT] AS decimal(8,2)) AS [FCANT], CAST(D.[FCFI] AS decimal(7,2)) AS [FCFI], CAST(D.[FCFITOT] AS decimal(15,4)) AS [FCFITOT], CAST(D.[FCOLTXT] AS varchar(50)) COLLATE DATABASE_DEFAULT AS [FCOLTXT], CAST(D.[FMTOIVA] AS decimal(15,4)) AS [FMTOIVA], CAST(D.[FNETO] AS decimal(15,4)) AS [FNETO], CAST(D.[FPORIVA] AS decimal(5,2)) AS [FPORIVA], CAST(D.[FPRECIO] AS decimal(12,2)) AS [FPRECIO], CAST(D.[FPRUN] AS decimal(15,2)) AS [FPRUN], CAST(D.[FTATXT] AS varchar(50)) COLLATE DATABASE_DEFAULT AS [FTATXT], CAST(D.[FTXT] AS varchar(100)) COLLATE DATABASE_DEFAULT AS [FTXT], CAST(D.[MNDESCI] AS decimal(15,4)) AS [MNDESCI], CAST(D.[MNTPIVA] AS decimal(17,4)) AS [MNTPIVA], CAST(D.[MNTPTOT] AS decimal(17,4)) AS [MNTPTOT], CAST(D.[PRUNCONIMP] AS decimal(15,4)) AS [PRUNCONIMP], CAST(D.[TALLE] AS varchar(5)) COLLATE DATABASE_DEFAULT AS [TALLE]
FROM (SELECT [CODIGO] AS [CODIGO], [DESCFW] AS [DESCFW], [FCLIENTE] AS [FCLIENTE], [FVEN] AS [FVEN], [MOTIVO] AS [MOTIVO], [FFCH] AS [FFCH], [FHORA] AS [FHORA], [FIMPUESTO] AS [FIMPUESTO], [FLETRA] AS [FLETRA], [FNUMCOMP] AS [FNUMCOMP], [FOBS] AS [FOBS], [FPERSON] AS [FPERSON], [FSUBTON] AS [FSUBTON], [FSUBTOT] AS [FSUBTOT], [FTOTAL] AS [FTOTAL], [FTURNO] AS [FTURNO], [FVUELTO] AS [FVUELTO], [GRAVAMEN] AS [GRAVAMEN], [HALTAFW] AS [HALTAFW], [IDCAJA] AS [IDCAJA], [IVASIS] AS [IVASIS], [REMITO] AS [REMITO], [SIGNOMOV] AS [SIGNOMOV], [UALTAFW] AS [UALTAFW],
                           ISNULL(CASE WHEN CHARINDEX(N' ', LTRIM(RTRIM([DESCFW] COLLATE DATABASE_DEFAULT)) + N' ') > 1
                      THEN LTRIM(RTRIM(LEFT(LTRIM(RTRIM([DESCFW] COLLATE DATABASE_DEFAULT)),
                          CHARINDEX(N' ', LTRIM(RTRIM([DESCFW] COLLATE DATABASE_DEFAULT)) + N' ') - 1)))
                      ELSE LTRIM(RTRIM([DESCFW] COLLATE DATABASE_DEFAULT)) END, N'') AS [_TIPO]
                    FROM [DRAGONFISH_VCPD].[ZooLogic].[COMPROBANTEV]
                     WHERE ISNULL(CASE WHEN CHARINDEX(N' ', LTRIM(RTRIM([DESCFW] COLLATE DATABASE_DEFAULT)) + N' ') > 1
                      THEN LTRIM(RTRIM(LEFT(LTRIM(RTRIM([DESCFW] COLLATE DATABASE_DEFAULT)),
                          CHARINDEX(N' ', LTRIM(RTRIM([DESCFW] COLLATE DATABASE_DEFAULT)) + N' ') - 1)))
                      ELSE LTRIM(RTRIM([DESCFW] COLLATE DATABASE_DEFAULT)) END, N'') IN ('DEVOLUCION')) AS C
INNER JOIN [DRAGONFISH_VCPD].[ZooLogic].[COMPROBANTEVDET] AS D
        ON C.[CODIGO] = D.[CODIGO];